<!doctype html><html lang="es-MX"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout</title><link rel="stylesheet" href="<?=cp_web_h(cp_web_route('/assets/css/checkout-v1.css'))?>"></head><body><main class="co-wrap"><p class="co-kicker">CHECKOUT</p><h1>Preparemos tu solicitud.</h1><div class="co-grid"><form class="co-form" method="post" action="<?=cp_web_h(cp_web_route('/checkout-procesar.php'))?>"><label>Nombre completo<input name="customer_name" required maxlength="190"></label><label>Teléfono<input name="phone" required maxlength="80"></label><label>Correo<input type="email" name="email" maxlength="190"></label><label>Dirección<input name="address"></label><div class="co-two"><label>Ciudad<input name="city"></label><label>Estado<input name="state"></label></div><div class="co-two"><label>C.P.<input name="zip_code"></label><label>Entrega<select name="delivery_method"><option value="pickup">Recoger / acordar</option><option value="shipping">Envío por cotizar</option></select></label></div><label>Notas<textarea name="notes" rows="5"></textarea></label><button>Enviar solicitud →</button></form><aside class="co-summary"><span>RESUMEN</span><h2>Tu pedido</h2><?php foreach($items as $i):?><div><span><?=cp_web_h($i['name'])?> × <?=$i['quantity']?></span><b><?= $i['sale_price']!==null&&$i['pricing_type']==='fixed'?cp_web_h(cp_web_money($i['sale_price']*$i['quantity'])):'Cotizar' ?></b></div><?php endforeach;?><div class="co-total"><span>Subtotal fijo</span><strong><?=cp_web_h(cp_web_money($totals['subtotal']))?></strong></div><?php if($totals['needs_quote']):?><p class="co-alert">Una línea requiere revisión antes de confirmar precio.</p><?php endif;?></aside></div></main></body></html>
